const ticket = $json.body || $json;
const notification = ticket.notification || {};
const groupId = notification.lineGroupId || ticket.lineGroupId || '';
const mentionUserIds = notification.mentionUserIds || [];
const shouldMention = Boolean(notification.shouldMention && mentionUserIds.length);

if (!groupId) {
  return [];
}

const lines = [
  ticket.urgency === '急件' ? '急件工單' : '人工工單',
  `類型：${ticket.topic || '未填'}`,
  `客戶：${ticket.customerName || '未填'}`,
  `聯絡人：${[ticket.contactPerson, ticket.phone].filter(Boolean).join(' ') || '未填'}`,
  ticket.relatedOrderId ? `訂單：${ticket.relatedOrderId}` : '',
  `內容：${ticket.message || '未填'}`,
  `工單：${ticket.requestId || '未填'}`,
].filter(Boolean);

if (!shouldMention) {
  return [{
    json: {
      to: groupId,
      messages: [{ type: 'text', text: lines.join('\n') }],
    },
  }];
}

const substitution = {};
const mentionTokens = mentionUserIds.map((userId, index) => {
  const key = `u${index + 1}`;
  substitution[key] = { type: 'mention', mentionee: { type: 'user', userId } };
  return `{${key}}`;
});

return [{
  json: {
    to: groupId,
    messages: [{
      type: 'textV2',
      text: `${mentionTokens.join(' ')}\n${lines.join('\n')}`,
      substitution,
    }],
  },
}];
